foundation.question_text:
Find the equation of the parabola shown, which has $x$-intercepts at $x=-3$ and $x=1$ and a $y$-intercept of $-3$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-5, xmax=3, ymin=-5.5, ymax=6, samples=100, clip=false, axis line style={-{Stealth}}, xtick={-3,-1,1}, ytick={-4,-2,2,4}]
\addplot[smooth, thick, blue, <->, domain=-4.16:2.16] {(x+3)*(x-1)};
\fill (axis cs:-3,0) circle (2.5pt);
\fill (axis cs:1,0) circle (2.5pt);
\fill (axis cs:0,-3) circle (2.5pt);
\node[above left] at (axis cs:-3,0) {$-3$};
\node[above right] at (axis cs:1,0) {$1$};
\node[right] at (axis cs:0,-3) {$-3$};
\end{axis}
\end{tikzpicture}
[/tikz]

development.question_text:
Find the equation of the parabola shown, which has vertex $(2,5)$ and passes through $(0,1)$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-3, xmax=6, ymin=-4, ymax=7, samples=100, clip=false, axis line style={-{Stealth}}, xtick={-2,2,4}, ytick={-2,2,4,6}]
\addplot[smooth, thick, blue, <->, domain=-1:5] {-(x-2)*(x-2)+5};
\fill (axis cs:2,5) circle (2.5pt);
\fill (axis cs:0,1) circle (2.5pt);
\node[above] at (axis cs:2,5) {$(2,5)$};
\node[left] at (axis cs:0,1) {$(0,1)$};
\end{axis}
\end{tikzpicture}
[/tikz]

Find the equation of the parabola shown, which has $x$-intercepts at $x=-5$ and $x=-1$ and a $y$-intercept of $-5$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$}, xmin=-7, xmax=1, ymin=-6, ymax=6, samples=100, clip=false, axis line style={-{Stealth}}, xtick={-5,-3,-1}, ytick={-4,-2,2,4}]
\addplot[smooth, thick, blue, <->, domain=-6.16:0.16] {-(x+5)*(x+1)};
\fill (axis cs:-5,0) circle (2.5pt);
\fill (axis cs:-1,0) circle (2.5pt);
\fill (axis cs:0,-5) circle (2.5pt);
\node[below left] at (axis cs:-5,0) {$-5$};
\node[below right] at (axis cs:-1,0) {$-1$};
\node[right] at (axis cs:0,-5) {$-5$};
\end{axis}
\end{tikzpicture}
[/tikz]
